/**
 * @name Template engine sandbox escape and code injection
 * @description Tracking untrusted template input to dangerous operations in Jinja2
 * @kind path-problem
 * @problem.severity error
 * @id py/jinja2-sandbox-escape
 * @tags security
 *        external/cwe/cwe-094
 *        external/cwe/cwe-095
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module Jinja2SandboxConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Template input sources - files, network, user input
    source instanceof RemoteFlowSource
    or
    // Jinja2 template loading from untrusted sources
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("jinja2").getMember(["Environment", "Template"]).getACall() and
      call.getArg(0) = source
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Code execution sinks
    sink = any(CodeExecution ce).getCode()
    or
    // Pickle deserialization sinks
    sink = API::moduleImport("pickle").getMember(["load", "loads", "Unpickler"]).getACall().getArg(0)
    or
    // Marshal deserialization sinks
    sink = API::moduleImport("marshal").getMember(["load", "loads"]).getACall().getArg(0)
    or
    // Eval/exec calls
    sink = API::builtin(["eval", "exec"]).getACall().getArg(0)
  }
}

module Jinja2SandboxFlow = TaintTracking::Global<Jinja2SandboxConfig>;
import Jinja2SandboxFlow::PathGraph

from Jinja2SandboxFlow::PathNode source, Jinja2SandboxFlow::PathNode sink
where Jinja2SandboxFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential sandbox escape or code injection from $@ to dangerous operation.", source.getNode(), "untrusted template input"
